export type Level = 'Foundations' | 'Intermediate' | 'Advanced';
export type Lesson = {
  id: string; title: string; summary: string; explain: string[]; code: string; output: string;
  watch: string; task: string; hint: string; solution: string;
  quiz: { question: string; options: string[]; correct: number; why: string };
};
export type Module = { id: string; title: string; description: string; level: Level; icon: string; topics: string[]; reference: string; lessons: Lesson[] };
const p = (imports: string, body: string, definitions = '') => `package main\n\n${imports ? `import (${imports})\n\n` : ''}${definitions ? definitions + '\n\n' : ''}func main() {\n${body}\n}\n`;
const q = (question: string, options: string[], correct: number, why: string) => ({ question, options, correct, why });

export const modules: Module[] = [
{id:'getting-started',title:'Your first steps in Go',description:'Get set up, meet the toolchain, and write your first real Go program.',level:'Foundations',icon:'terminal',topics:['Installation','Modules','Packages','go run','gofmt'],reference:'https://go.dev/doc/tutorial/getting-started',lessons:[
{id:'hello-go',title:'Hello, Go. Meet your toolchain.',summary:'One file, one function, and a surprisingly useful set of tools.',explain:["Go programs are organized into packages. A runnable program uses package main and starts in func main(). The fmt package provides formatted input and output; Println writes a line to standard output.","Install Go from go.dev/dl and check go version in a terminal. Create a directory, run go mod init example.com/hello, and save the example as main.go. Run it with go run .; build a standalone executable with go build .; format your source with gofmt -w main.go."],code:p('"fmt"','  fmt.Println("Hello, Go!")'),output:'Hello, Go!\n',watch:'Go rejects unused imports and local variables. Import a package when the program actually uses it.',task:'Change the greeting to Hello, developer! and print a second line saying Let’s build something.',hint:'Call fmt.Println once for each line.',solution:'Replace the existing call with fmt.Println("Hello, developer!") and add fmt.Println("Let’s build something."). Each Println adds a newline.',quiz:q('Where does a runnable Go program begin?',['In init()','In main() inside package main','In the first file alphabetically'],1,'A command starts by initializing packages, then calling main.main. init functions support initialization, not the main entry point.')},
{id:'modules-packages',title:'Modules, packages, and visibility',summary:'Understand the boundaries that keep a Go project simple.',explain:['A module is a versioned collection of packages, identified by the module path in go.mod. A package is a set of source files compiled together from one directory. Import paths combine the module path with a package’s directory.','Names beginning with an uppercase letter are exported to other packages. Lowercase names stay inside their package. Keep packages focused on a capability, such as billing, instead of collecting unrelated helpers. Use go mod tidy to reconcile declared dependencies with imports.'],code:p('"fmt"','  fmt.Println(Greeting("Priya"))','// Greeting is exported; greeting would be package-private.\nfunc Greeting(name string) string {\n  return "Hello, " + name\n}'),output:'Hello, Priya\n',watch:'An exported name is visible to importers, but the main package itself is a command, not a reusable library.',task:'Create a greeting subdirectory with package greeting, export Hello, and call it from main.',hint:'For module example.com/hello, import example.com/hello/greeting.',solution:'Move the function to greeting/greeting.go, change its package to greeting and its name to Hello, then import "example.com/hello/greeting" in main.go and call greeting.Hello("Priya").',quiz:q('What makes a package identifier exported?',['A public keyword','An uppercase first letter','Its file is named public.go'],1,'Go uses the identifier’s initial letter to control package visibility.')},
{id:'tooling-workflow',title:'The everyday Go workflow',summary:'Format, inspect, test, and build without a complicated tool setup.',explain:['Use gofmt for consistent formatting, go vet ./... for suspicious patterns, go test ./... for package tests, and go build ./... to compile the project. The ./... pattern walks packages below the current directory, subject to module boundaries.','Documentation comments start with the declared name. Read package documentation with go doc fmt.Printf. For a new dependency, go get its import path at an intentional version and commit go.mod and go.sum. go.sum verifies downloaded module content; it is not a complete dependency lockfile.'],code:p('"fmt"','  fmt.Printf("%s: %d checks passed\\n", "build", 4)'),output:'build: 4 checks passed\n',watch:'A successful build does not prove behavior is correct. Tests, vet, and the race detector answer different questions.',task:'Run gofmt, go vet, go test, and go build against a small module. Read go doc fmt.Printf.',hint:'Keep these commands in your project README or CI configuration.',solution:'Run gofmt -w ., go vet ./..., go test ./..., and go build ./... from the module root. A module with no test files can pass go test without testing any behavior.',quiz:q('Which command flags suspicious code patterns?',['go vet ./...','go mod init','go clean'],0,'go vet analyzes suspicious constructs; it complements compilation and tests.')}
]},
{id:'language-basics',title:'Think in Go',description:'Types, control flow, and functions—the building blocks you will use every day.',level:'Foundations',icon:'braces',topics:['Types','Zero values','Constants','Loops','Functions','Closures'],reference:'https://go.dev/tour/basics/1',lessons:[
{id:'variables-types',title:'Variables, types, and useful zero values',summary:'Know what a value means before doing anything with it.',explain:['Use var for an explicit declaration and := for a new local variable with inferred type. Uninitialized values receive a zero value: 0 for numbers, false for booleans, and "" for strings. Package-level declarations use var or const, not :=.','Go does not implicitly mix numeric types. Convert deliberately with expressions such as float64(total). Constants represent fixed values; untyped numeric constants can fit the type required by their context. Use iota for related constants when it improves clarity.'],code:p('"fmt"','  var retries int\n  name := "worker"\n  const limit = 3\n  fmt.Printf("%s: %d/%d\\n", name, retries, limit)\n  fmt.Println(float64(5) / 2)'),output:'worker: 0/3\n2.5\n',watch:'Integer division truncates before a later conversion. float64(5 / 2) is 2, not 2.5.',task:'Print a completion percentage for 3 completed tasks out of 8.',hint:'Convert before dividing, then multiply by 100.',solution:'Use percent := float64(3) / float64(8) * 100 and fmt.Printf("%.1f%%\\n", percent). The result is 37.5%.',quiz:q('What is the zero value of bool?',['nil','true','false'],2,'Every bool starts as false unless explicitly initialized.')},
{id:'control-flow',title:'Conditions, loops, and switch',summary:'Express decisions without extra syntax.',explain:['Go has one loop keyword: for. It supports a traditional initializer-condition-update form, a condition-only form, an infinite loop, and range iteration. Use break to exit and continue to skip to the next iteration.','if can include a short initialization statement. switch evaluates cases in order and stops after the matching case unless fallthrough is explicit. A switch with no expression behaves like a readable chain of boolean conditions.'],code:p('"fmt"','  for n := 1; n <= 3; n++ {\n    switch {\n    case n%2 == 0:\n      fmt.Println(n, "even")\n    default:\n      fmt.Println(n, "odd")\n    }\n  }'),output:'1 odd\n2 even\n3 odd\n',watch:'Go switch cases do not fall through automatically. Loop conditions have no surrounding parentheses.',task:'Print the numbers from 1 through 10, skipping multiples of 3.',hint:'Use continue when n%3 == 0.',solution:'Loop with for n := 1; n <= 10; n++ { if n%3 == 0 { continue }; fmt.Println(n) }. The remaining numbers are 1, 2, 4, 5, 7, 8, and 10.',quiz:q('What does continue do?',['Exits the function','Skips the rest of this loop iteration','Repeats the previous statement'],1,'continue moves to the next iteration of the innermost enclosing loop.')},
{id:'functions-closures',title:'Functions, multiple returns, and closures',summary:'Return useful results and capture just the state you need.',explain:['Functions declare parameter names before types and may return multiple values. A common shape is (result, error), so callers can handle expected failures explicitly. Variadic parameters such as values ...int accept a variable number of arguments.','Functions are values: pass them to other functions or return them. A closure remembers variables from its surrounding scope. Here each call updates the same captured counter. Separate calls to makeCounter create independent counters.'],code:p('"fmt"','  next := makeCounter()\n  fmt.Println(next(), next())\n  fmt.Println(sum(2, 3, 4))','func makeCounter() func() int {\n  count := 0\n  return func() int { count++; return count }\n}\nfunc sum(values ...int) int {\n  total := 0\n  for _, value := range values { total += value }\n  return total\n}'),output:'1 2\n9\n',watch:'Captured mutable state needs synchronization if multiple goroutines access it concurrently.',task:'Create two counters and verify that advancing one does not advance the other.',hint:'Call makeCounter twice and store both returned functions.',solution:'Use a, b := makeCounter(), makeCounter(); fmt.Println(a(), a(), b()). The output is 1 2 1 because each call to makeCounter creates a different count variable.',quiz:q('What does a closure capture?',['A copy of every global','Variables from its enclosing scope','Only constants'],1,'A closure can refer to variables declared in its surrounding lexical scope.')}
]},
{id:'collections',title:'Collections & memory',description:'Work confidently with slices, maps, pointers, strings, and Unicode.',level:'Foundations',icon:'layers',topics:['Arrays','Slices','Maps','Pointers','Unicode','Ownership'],reference:'https://go.dev/blog/slices-intro',lessons:[
{id:'arrays-slices',title:'Slices are views, not independent arrays',summary:'Understand length, capacity, append, and shared storage.',explain:['An array has a fixed length that is part of its type, such as [3]int. A slice describes a window over an underlying array with a pointer, length, and capacity. Slicing usually shares storage; changing an element through one view can change another.','append returns a new slice header. If capacity is sufficient, the existing array is reused; otherwise Go allocates a larger one. Always keep append’s return value. To detach data, allocate a destination and copy the elements, or use slices.Clone for a shallow copy.'],code:p('"fmt"','  original := []int{10, 20, 30}\n  view := original[:2]\n  view[0] = 99\n  detached := append([]int(nil), original...)\n  detached[0] = 1\n  fmt.Println(original)\n  fmt.Println(view)\n  fmt.Println(detached)'),output:'[99 20 30]\n[99 20]\n[1 20 30]\n',watch:'Copying a slice value does not copy its elements. A shallow clone also leaves nested maps, pointers, and slices shared.',task:'Create a copy of []string{"api", "worker"} and change only the copy.',hint:'Use make and copy, or slices.Clone.',solution:'Use source := []string{"api", "worker"}; target := make([]string, len(source)); copy(target, source); target[0] = "cli". source[0] remains "api".',quiz:q('What usually happens when you slice an existing slice?',['All elements are copied','The underlying storage is shared','The original is cleared'],1,'Slicing creates another descriptor that generally points into the same backing array.')},
{id:'maps-sets',title:'Maps, lookups, and sets',summary:'Distinguish a missing key from a stored zero value.',explain:['Maps associate comparable keys with values. Use make(map[string]int) or a map literal before writing. A missing key returns the value type’s zero value; the comma-ok form also tells you whether the key exists.','Use delete to remove a key. A set can be represented by map[T]struct{}. Map iteration order is unspecified, so sort keys when output must be stable. Plain maps do not support unsynchronized concurrent reads and writes.'],code:p('"fmt"','  scores := map[string]int{"Ada": 0, "Lin": 7}\n  score, exists := scores["Ada"]\n  fmt.Println(score, exists)\n  score, exists = scores["Sam"]\n  fmt.Println(score, exists)\n  delete(scores, "Lin")\n  fmt.Println(len(scores))'),output:'0 true\n0 false\n1\n',watch:'Reading a nil map is valid; writing to one panics. Initialize it before assigning entries.',task:'Count repeated words in []string{"go", "build", "go"}.',hint:'A missing integer entry starts at zero, so counts[word]++ works.',solution:'Create counts := make(map[string]int), loop over the words, and increment counts[word]. Look up counts["go"] to get 2. Sort keys before printing the whole result deterministically.',quiz:q('How do you distinguish a missing key from a stored zero?',['Compare with nil','Use value, ok := m[key]','Call len(value)'],1,'The second result reports key presence independently of the stored value.')},
{id:'pointers-unicode',title:'Pointers, strings, and Unicode',summary:'Separate where data lives from how text is encoded.',explain:['A pointer stores the address of a value. &value takes its address; *pointer accesses the value it points to. Go passes arguments by value, including pointers. A pointer lets a function modify the original value without copying the entire object.','A string is an immutable byte sequence, conventionally UTF-8 text. len counts bytes, while range decodes runes (Unicode code points). A visible character can contain multiple code points, so rune count is not always the number of user-perceived characters.'],code:p('"fmt"; "unicode/utf8"','  count := 4\n  increment(&count)\n  text := "Go世界"\n  fmt.Println(count)\n  fmt.Println(len(text), utf8.RuneCountInString(text))\n  for _, r := range text { fmt.Printf("%c ", r) }\n  fmt.Println()','func increment(n *int) { *n = *n + 1 }'),output:'5\n8 4\nG o 世 界 \n',watch:'Dereferencing a nil pointer panics. Indexing a UTF-8 string yields a byte, not necessarily a whole character.',task:'Reverse the code points in "Go世界" without corrupting UTF-8.',hint:'Convert to []rune, swap from both ends, then convert back to string.',solution:'Use chars := []rune("Go世界"); for i, j := 0, len(chars)-1; i < j; i, j = i+1, j-1 { chars[i], chars[j] = chars[j], chars[i] }; fmt.Println(string(chars)). This reverses code points, not grapheme clusters.',quiz:q('What does len("世界") return in UTF-8?',['2','6','It does not compile'],1,'Each of these two code points uses three UTF-8 bytes, so the byte length is 6.')}
]},
{id:'types-interfaces',title:'Design with types',description:'Model behavior with structs, methods, small interfaces, and generics.',level:'Foundations',icon:'box',topics:['Structs','Methods','Interfaces','Embedding','Generics','Type assertions'],reference:'https://go.dev/tour/methods/1',lessons:[
{id:'structs-methods',title:'Structs, methods, and composition',summary:'Group data and give it behavior without inheritance.',explain:['A struct groups named fields. Methods attach behavior to a named type. Use a pointer receiver when the method must mutate the value, or copying the value would be inappropriate. A value receiver works on a copy.','Embedding promotes methods and fields from an embedded field. It is composition: the outer type contains the inner type. Prefer explicit named fields when ownership or behavior would otherwise be surprising. Keep receiver choices consistent for a type, especially if it contains a lock.'],code:p('"fmt"','  account := Account{Owner: "Ada"}\n  account.Deposit(25)\n  fmt.Println(account.Owner, account.Balance)','type Account struct {\n  Owner string\n  Balance int\n}\nfunc (a *Account) Deposit(amount int) { a.Balance += amount }'),output:'Ada 25\n',watch:'Exporting mutable fields makes invariants harder to enforce. Production money calculations need a deliberate representation and validation.',task:'Reject deposits of zero or negative amounts by returning an error.',hint:'Change Deposit to return error; validate before changing Balance.',solution:'Use func (a *Account) Deposit(amount int) error { if amount <= 0 { return fmt.Errorf("amount must be positive") }; a.Balance += amount; return nil }. Handle the returned error at the call site.',quiz:q('Why use a pointer receiver for Deposit?',['To modify the original account','To make it run asynchronously','All methods require pointers'],0,'A pointer receiver allows the method to update the caller’s account.')},
{id:'small-interfaces',title:'Small interfaces, implicit satisfaction',summary:'Describe the behavior a caller needs, not an entire object.',explain:['An interface is a set of methods. A type satisfies it implicitly by implementing those methods; no implements declaration is needed. Define small interfaces near their consumers. io.Reader and io.Writer are useful examples of focused contracts.','An interface value contains a dynamic type and a dynamic value. A typed nil pointer stored in an interface can make the interface itself non-nil. Use comma-ok type assertions to inspect optional capabilities without panicking. A type switch handles several dynamic types.'],code:p('"fmt"; "io"; "strings"','  var source io.Reader = strings.NewReader("go")\n  data, err := io.ReadAll(source)\n  if err != nil { panic(err) }\n  fmt.Println(string(data))\n  _, seekable := source.(io.Seeker)\n  fmt.Println("seekable:", seekable)'),output:'go\nseekable: true\n',watch:'A *T method belongs to *T’s method set. A T value may not satisfy an interface requiring that method, even when an ordinary method call can take its address.',task:'Define a Greeter interface and implement it with a Person struct.',hint:'The interface needs only Greet() string.',solution:'Declare type Greeter interface { Greet() string }; type Person struct { Name string }; func (p Person) Greet() string { return "Hi, " + p.Name }. Assign Person{Name:"Ada"} to a Greeter variable.',quiz:q('When does a type satisfy an interface?',['When it declares implements','When its method set includes the required methods','When it is embedded in the interface'],1,'Interface satisfaction is implicit and determined by method sets.')},
{id:'generics',title:'Generics where they earn their place',summary:'Share type-safe algorithms without hiding the domain.',explain:['Type parameters let a function or type operate over a constrained set of types. comparable permits equality checks and map keys. any means an unconstrained type parameter. Use generics when the algorithm is genuinely the same across types.','A constraint can describe allowed underlying types, such as ~int | ~int64. The tilde also admits named types with that underlying type. Prefer an interface when behavior is the shared abstraction; use type parameters when preserving the concrete type matters.'],code:p('"fmt"','  fmt.Println(Unique([]string{"go", "go", "ship"}))\n  fmt.Println(Unique([]int{2, 2, 3}))','func Unique[T comparable](values []T) []T {\n  seen := make(map[T]bool)\n  result := make([]T, 0, len(values))\n  for _, value := range values {\n    if !seen[value] { seen[value] = true; result = append(result, value) }\n  }\n  return result\n}'),output:'[go ship]\n[2 3]\n',watch:'Not every type is comparable. A slice cannot be a map key or satisfy comparable as a concrete type argument.',task:'Write First[T any] that returns the first item and a bool indicating whether it exists.',hint:'Declare var zero T for the empty case.',solution:'Use func First[T any](items []T) (T, bool) { if len(items) == 0 { var zero T; return zero, false }; return items[0], true }. The bool distinguishes a missing item from a real zero value.',quiz:q('Why does Unique require comparable?',['It prints values','Its map keys need equality support','Generics always require comparable'],1,'The map uses T as its key type, so T must support comparison.')}
]},
{id:'errors-resources',title:'Errors & resource lifecycles',description:'Handle failures explicitly and make cleanup reliable.',level:'Foundations',icon:'shield',topics:['Errors','Wrapping','errors.Is','errors.As','defer','panic'],reference:'https://go.dev/blog/go1.13-errors',lessons:[
{id:'error-values',title:'Errors are values',summary:'Return a failure the caller can understand and act on.',explain:['An error is a value implementing Error() string. Return errors for expected failures and check them at the call site. Add context when it tells the caller which operation failed. Avoid logging and returning the same error at every layer.','Sentinel errors describe stable conditions that callers may compare using errors.Is. For detailed structured information, define an error type and inspect it with errors.As. Error text is for people; do not parse it to decide program behavior.'],code:p('"errors"; "fmt"','  _, err := divide(10, 0)\n  if errors.Is(err, ErrZero) { fmt.Println("choose a non-zero divisor") }','var ErrZero = errors.New("division by zero")\nfunc divide(a, b int) (int, error) {\n  if b == 0 { return 0, ErrZero }\n  return a / b, nil\n}'),output:'choose a non-zero divisor\n',watch:'Ignoring an error can turn the original failure into a later, harder-to-diagnose problem. Only discard one deliberately.',task:'Handle both a successful division and a zero divisor.',hint:'Inspect err before using the returned result.',solution:'Call result, err := divide(10, 2); if err != nil { fmt.Println(err); return }; fmt.Println(result). This prints 5. Keep a separate test for divide(10, 0).',quiz:q('What should callers use to recognize a wrapped sentinel error?',['Compare err.Error() strings','errors.Is','Print the error'],1,'errors.Is follows supported wrapping chains and matches the target condition.')},
{id:'wrapping-errors',title:'Wrap context, preserve the cause',summary:'Explain what failed without losing a machine-readable error.',explain:['fmt.Errorf with %w wraps an error. The added message explains the operation; errors.Is and errors.As can still inspect the cause. With %v you get readable text but do not preserve the wrapping relationship.','Use errors.As when callers need fields from a typed error, such as an operating-system path failure. Keep error messages concise, usually lowercase without trailing punctuation, so wrapping reads naturally.'],code:p('"errors"; "fmt"; "io/fs"','  err := fmt.Errorf("load settings: %w", fs.ErrNotExist)\n  fmt.Println(err)\n  fmt.Println(errors.Is(err, fs.ErrNotExist))'),output:'load settings: file does not exist\ntrue\n',watch:'Wrapping exposes the underlying condition as part of your API. Decide which details callers should depend on.',task:'Wrap a failed operation twice and verify errors.Is still recognizes fs.ErrNotExist.',hint:'Each layer must use %w for the original cause to remain reachable.',solution:'Set err := fmt.Errorf("startup: %w", fmt.Errorf("load settings: %w", fs.ErrNotExist)); errors.Is(err, fs.ErrNotExist) returns true.',quiz:q('Which formatting verb preserves an error for unwrapping?',['%s','%v','%w'],2,'%w creates an error-wrapping relationship in fmt.Errorf.')},
{id:'defer-panic',title:'Defer, cleanup, and panic boundaries',summary:'Make resource ownership obvious.',explain:['defer schedules a call for when the surrounding function returns. Deferred calls run in last-in-first-out order, and their arguments are evaluated when defer is executed. Put cleanup immediately after acquiring a resource successfully.','panic unwinds the stack and runs deferred calls. recover can stop a panic only when called directly in an appropriate deferred function on the same goroutine. Use ordinary errors for expected failures; reserve recovery for deliberate process or request boundaries.'],code:p('"fmt"','  defer fmt.Println("cleanup A")\n  defer fmt.Println("cleanup B")\n  value := 1\n  defer fmt.Println("captured:", value)\n  value = 2\n  fmt.Println("working:", value)'),output:'working: 2\ncaptured: 1\ncleanup B\ncleanup A\n',watch:'defer inside a long loop waits until the surrounding function returns. A per-iteration helper can release resources earlier. Check Close errors when they matter, especially for writes.',task:'Predict the output after moving the first defer below the second.',hint:'Think in reverse registration order.',solution:'Swapping the first two defer lines changes the final cleanup order to cleanup A then cleanup B. The captured value still prints 1.',quiz:q('When are deferred function arguments evaluated?',['When the defer statement executes','Only when the function returns','After all other defers'],0,'The call is delayed, but its argument expressions are evaluated immediately.')}
]},
{id:'standard-library',title:'The standard library toolkit',description:'Read streams, encode data, and work with time using Go’s core packages.',level:'Intermediate',icon:'library',topics:['io.Reader','Files','JSON','Time','Regular expressions','Context'],reference:'https://pkg.go.dev/std',lessons:[
{id:'io-streams',title:'Readers, writers, and streaming',summary:'Build reusable pipelines around tiny interfaces.',explain:['io.Reader reads bytes into a caller-provided buffer. io.Writer accepts bytes. These interfaces work with files, network connections, buffers, compression streams, and more, so code can depend on behavior rather than a particular storage system.','Use io.Copy to stream between a reader and writer. A Reader may return useful bytes and an error together: process n > 0 bytes before acting on the error. Bound untrusted input with a size policy; a limit alone does not report that the original input was larger.'],code:p('"bytes"; "fmt"; "io"; "strings"','  source := strings.NewReader("small streams compose")\n  var destination bytes.Buffer\n  n, err := io.Copy(&destination, io.LimitReader(source, 5))\n  if err != nil { panic(err) }\n  fmt.Println(n, destination.String())'),output:'5 small\n',watch:'io.ReadAll buffers the whole stream. For large or attacker-controlled bodies, use a deliberate size bound or stream incrementally.',task:'Copy only the first 4 bytes of "Go is great" into a buffer.',hint:'Wrap the source with io.LimitReader(source, 4).',solution:'Use io.Copy(&destination, io.LimitReader(strings.NewReader("Go is great"), 4)). The buffer contains "Go i". These limits count bytes, not Unicode characters.',quiz:q('Why accept io.Reader instead of *os.File?',['To require disk access','To support many data sources','To avoid handling errors'],1,'A behavior-based interface allows files, buffers, sockets, and test doubles to work with the same code.')},
{id:'json-files',title:'JSON, struct tags, and file boundaries',summary:'Translate data without losing validation.',explain:['encoding/json maps exported struct fields to JSON properties. Struct tags such as json:"name" choose wire names. omitempty omits certain empty values when encoding; pointer fields can help distinguish absent data from an explicit zero in an API.','Decode, then validate domain rules separately. Decoder.DisallowUnknownFields rejects unexpected fields, useful for strict request bodies. To require a single JSON document, attempt a second decode and require io.EOF. Use os.ReadFile and os.WriteFile for small files; stream larger ones.'],code:p('"encoding/json"; "fmt"; "strings"','  var user User\n  decoder := json.NewDecoder(strings.NewReader(`{"name":"Ada","active":true}`))\n  decoder.DisallowUnknownFields()\n  if err := decoder.Decode(&user); err != nil { panic(err) }\n  fmt.Println(user.Name, user.Active)','type User struct {\n  Name string `json:"name"`\n  Active bool `json:"active"`\n}'),output:'Ada true\n',watch:'Unexported fields are not populated. Decoding successfully does not validate required names, ranges, or authorization.',task:'Add an age field and reject ages below zero.',hint:'Add Age int with a JSON tag, then validate after Decode.',solution:'Add Age int `json:"age"` to User, decode the body, and check if user.Age < 0 before using it. In HTTP handlers, return a client error rather than panic.',quiz:q('Does JSON decoding enforce your business rules?',['Yes, always','Only for tagged fields','No, validate them explicitly'],2,'Decoding checks representation and types, not application rules such as a nonnegative age.')},
{id:'time-regexp',title:'Time, durations, and text matching',summary:'Parse timestamps and patterns deliberately.',explain:['time.Duration represents elapsed time. time.Time represents an instant with additional location and possibly monotonic-clock information. Use time.Since(start) for elapsed measurements and time.RFC3339 for interoperable timestamps. Parse layouts use the reference date Mon Jan 2 15:04:05 MST 2006.','Compile reusable regular expressions once. Go’s regexp package does not support features such as lookbehind or backreferences. For straightforward prefixes or substring checks, strings.HasPrefix and strings.Contains usually express intent more directly.'],code:p('"fmt"; "regexp"; "time"','  instant, err := time.Parse(time.RFC3339, "2026-10-16T09:00:00Z")\n  if err != nil { panic(err) }\n  fmt.Println(instant.Add(90 * time.Minute).Format(time.RFC3339))\n  valid := regexp.MustCompile(`^[a-z][a-z0-9-]{2,15}$`)\n  fmt.Println(valid.MatchString("go-worker"))'),output:'2026-10-16T10:30:00Z\ntrue\n',watch:'A day is not always 24 hours in a local timezone. Calendar arithmetic and elapsed duration are different operations.',task:'Parse 250ms with time.ParseDuration and print its milliseconds.',hint:'The returned duration has a Milliseconds method.',solution:'Use d, err := time.ParseDuration("250ms"); handle err; fmt.Println(d.Milliseconds()). This prints 250.',quiz:q('Which layout constant is useful for interoperable timestamps?',['time.RFC3339','"YYYY-MM-DD"','time.Second'],0,'time.RFC3339 describes a widely used timestamp format with timezone information.')}
]},
{id:'concurrency',title:'Concurrency that makes sense',description:'Coordinate work, share state safely, and stop goroutines reliably.',level:'Intermediate',icon:'network',topics:['Goroutines','Channels','select','Mutexes','WaitGroup','Cancellation'],reference:'https://go.dev/doc/effective_go#concurrency',lessons:[
{id:'goroutines-channels',title:'Goroutines and channels',summary:'Start work concurrently, then coordinate its result.',explain:['A goroutine is a concurrently executing function. Starting one does not wait for it. If main returns, the program ends even if other goroutines are still running. Coordinate completion explicitly using a channel or a synchronization primitive.','An unbuffered channel synchronizes sender and receiver. A buffered channel permits a limited number of queued values. The sender or coordinator should close a channel when no more sends will happen; receivers range until the channel is closed and drained.'],code:p('"fmt"','  results := make(chan int)\n  go func() {\n    for n := 1; n <= 3; n++ { results <- n * n }\n    close(results)\n  }()\n  for result := range results { fmt.Println(result) }'),output:'1\n4\n9\n',watch:'Sending on a closed channel panics. Operations on a nil channel block forever unless another select case can proceed.',task:'Send the first five even numbers through a channel and sum them in main.',hint:'Have the producing goroutine close the channel.',solution:'Send 2, 4, 6, 8, and 10, then close. In main, range over the channel and accumulate total. Print 30 after the loop ends.',quiz:q('Who should normally close a channel?',['Any receiver when it is bored','The sender or coordinator that knows sends are finished','Every goroutine'],1,'Closing announces that no further values will be sent, so it belongs with ownership of sending.')},
{id:'mutex-waitgroup',title:'Protect shared state with a mutex',summary:'A goroutine does not make a read-modify-write operation safe.',explain:['When goroutines share mutable data, protect every conflicting access with the same synchronization strategy. A mutex creates a critical section. WaitGroup tracks completion; its counter is separate from protection of the data being updated.','Call Add before launching the associated goroutines, call Done on every exit path, and Wait before reading results that require all workers to finish. Do not copy a mutex or WaitGroup after first use. Use go test -race ./... to detect races exercised by tests.'],code:p('"fmt"; "sync"','  var mu sync.Mutex\n  var wg sync.WaitGroup\n  count := 0\n  for i := 0; i < 100; i++ {\n    wg.Add(1)\n    go func() {\n      defer wg.Done()\n      mu.Lock(); count++; mu.Unlock()\n    }()\n  }\n  wg.Wait()\n  fmt.Println(count)'),output:'100\n',watch:'WaitGroup alone does not make count++ atomic. A passing race-detector run only covers the execution paths that actually ran.',task:'Change the example so each goroutine increments the counter twice under the same lock.',hint:'Keep both increments inside the critical section.',solution:'Use mu.Lock(); count += 2; mu.Unlock(). With 100 workers, the final result is 200 after wg.Wait returns.',quiz:q('What does WaitGroup protect?',['All shared variables','Completion coordination, not arbitrary shared data','Every channel send'],1,'WaitGroup waits for work to finish. A separate mutex or atomic operation protects concurrent access to count.')},
{id:'context-select',title:'Cancellation, select, and bounded work',summary:'Give every goroutine a way to finish.',explain:['context.Context carries cancellation, deadlines, and request-scoped values across API boundaries. Accept it as the first argument, pass it down, and call the cancel function when you create a derived context. Cancellation is cooperative: your code must observe it.','select waits for one ready channel operation. A ctx.Done case lets blocked work exit. When multiple cases are ready, selection is not a priority mechanism. Bound parallelism with a worker pool or semaphore so a traffic spike does not launch unlimited work.'],code:p('"context"; "fmt"','  ctx, cancel := context.WithCancel(context.Background())\n  cancel()\n  select {\n  case <-ctx.Done():\n    fmt.Println(ctx.Err())\n  default:\n    fmt.Println("still working")\n  }'),output:'context canceled\n',watch:'Passing a context does not cancel a function automatically. Blocking I/O must use context-aware APIs or a deliberate interruption mechanism.',task:'Create a worker that waits for a job or cancellation without leaking a goroutine.',hint:'Use select with jobs and ctx.Done; check the receive’s ok value.',solution:'Inside a loop: select { case job, ok := <-jobs: if !ok { return }; process(job); case <-ctx.Done(): return }. If process itself blocks, it must also cooperate with cancellation.',quiz:q('What makes context cancellation effective?',['The runtime kills every goroutine','The code observes cancellation and returns','The context variable becomes nil'],1,'Cancellation is a signal. Work must honor it, especially when waiting on channels or I/O.')}
]},
{id:'testing',title:'Testing & debugging',description:'Build confidence through behavior-focused tests and measured feedback.',level:'Intermediate',icon:'flask',topics:['testing','Table tests','Fuzzing','Benchmarks','Race detector','httptest'],reference:'https://go.dev/doc/tutorial/add-a-test',lessons:[
{id:'table-tests',title:'Table-driven tests and useful failures',summary:'Make edge cases easy to see and extend.',explain:['Go discovers tests in files ending in _test.go. A test has the shape func TestName(t *testing.T). Table-driven tests store inputs and expected results as cases, then run each with t.Run for independent diagnostics.','Assert externally meaningful behavior. Include empty input, boundary conditions, and invalid data where relevant. Use t.Fatalf to stop a case when continuing would be meaningless. The runnable example below demonstrates the same case table without importing a test runner.'],code:p('"fmt"; "strings"','  cases := []struct { input, want string }{\n    {" go ", "go"}, {"", ""}, {"Go", "Go"},\n  }\n  for _, tc := range cases {\n    got := strings.TrimSpace(tc.input)\n    fmt.Println(got == tc.want)\n  }'),output:'true\ntrue\ntrue\n',watch:'Do not assert unimportant implementation details. A test should fail because behavior changed, not because code was rearranged.',task:'Convert the example into TestTrim in trim_test.go.',hint:'Import testing and use t.Run with a readable case name.',solution:'Write func TestTrim(t *testing.T) { for _, tc := range cases { t.Run(tc.input, func(t *testing.T) { if got := strings.TrimSpace(tc.input); got != tc.want { t.Fatalf("TrimSpace(%q) = %q; want %q", tc.input, got, tc.want) } }) } }. Keep cases inside the test or at package scope, and run go test ./....',quiz:q('What is a useful table-test case?',['The implementation’s local variable name','An empty input with an explicit expected result','Only a successful nonempty input'],1,'Boundary cases describe observable behavior and often reveal mistakes missed by the happy path.')},
{id:'fuzz-properties',title:'Fuzz invariants, not random guesses',summary:'Check a property over many generated inputs.',explain:['A fuzz test accepts *testing.F, adds seed cases with f.Add, and calls f.Fuzz with supported input types. Run it with go test -fuzz=FuzzName. Useful properties include round trips, idempotence, and preserving valid representations.','Fuzzing extends coverage beyond hand-written cases, but the property must be valid. For example, JSON round-tripping an arbitrary byte string need not preserve invalid UTF-8. Choose a domain where the invariant holds. This example checks a binary-safe hexadecimal round trip.'],code:p('"encoding/hex"; "fmt"','  original := []byte{0, 127, 255}\n  encoded := hex.EncodeToString(original)\n  decoded, err := hex.DecodeString(encoded)\n  if err != nil { panic(err) }\n  fmt.Println(encoded)\n  fmt.Printf("%v\\n", decoded)'),output:'007fff\n[0 127 255]\n',watch:'A failing fuzz input is valuable regression data. Keep minimized cases rather than dismissing them as unrealistic.',task:'Write FuzzHexRoundTrip for a []byte input and compare decoded bytes with the original.',hint:'Use bytes.Equal; add empty and non-ASCII seed inputs.',solution:'In a _test.go file, write func FuzzHexRoundTrip(f *testing.F) { f.Add([]byte{0,255}); f.Fuzz(func(t *testing.T, input []byte) { got, err := hex.DecodeString(hex.EncodeToString(input)); if err != nil || !bytes.Equal(got, input) { t.Fatal("round trip failed") } }) }. Import testing, encoding/hex, and bytes.',quiz:q('What does a good fuzz property describe?',['A valid invariant across the chosen input domain','The exact random seed sequence','A single example string'],0,'The property defines correctness; the fuzz engine explores inputs that might break it.')},
{id:'benchmarks-debugging',title:'Benchmark before optimizing',summary:'Separate a measurement from a hunch.',explain:['Benchmarks live in _test.go files and use func BenchmarkName(b *testing.B). Run go test -bench=. -benchmem to report timing and allocations. Keep setup out of the measured section where appropriate and compare repeated runs under similar conditions.','Use go test -race for exercised data races, go vet for suspicious patterns, and debugger breakpoints for control flow and state. A CPU or heap profile helps locate actual hot spots. Timing one tiny operation once is usually noise, not evidence.'],code:p('"fmt"; "strings"','  var builder strings.Builder\n  builder.Grow(12)\n  for _, word := range []string{"Go", " ", "by", " ", "Doing"} {\n    builder.WriteString(word)\n  }\n  fmt.Println(builder.String())'),output:'Go by Doing\n',watch:'A microbenchmark can improve while the real service gets slower. Measure the workload and resource that matter to users.',task:'Benchmark repeated string concatenation against strings.Builder for the same workload.',hint:'Keep the produced result observable and compare allocations as well as time.',solution:'Write two Benchmark functions, build identical strings inside each iteration, and store the final result in a package-level string sink. Run go test -bench=. -benchmem -count=5. Compare distributions; do not invent a speedup before measuring.',quiz:q('Which command also reports allocations in benchmarks?',['go test -bench=. -benchmem','go build -race','go fmt -bench'],0,'-bench selects benchmarks and -benchmem adds allocation statistics.')}
]},
{id:'http-services',title:'Build HTTP services',description:'Serve requests, compose middleware, and make reliable outbound calls.',level:'Intermediate',icon:'globe',topics:['net/http','Routing','Middleware','Clients','Timeouts','httptest'],reference:'https://pkg.go.dev/net/http',lessons:[
{id:'http-handlers',title:'Your first HTTP handler',summary:'Turn a request into an explicit response.',explain:['An http.Handler serves a request through ServeHTTP(ResponseWriter, *Request). http.HandlerFunc adapts a function to that interface. ServeMux routes incoming requests; modern Go versions support method-aware patterns such as GET /health.','Set headers before writing a status or body. The first Write implicitly sends status 200 if no status has been written. httptest lets you exercise a handler without opening a network port, which also makes this example work in the sandbox.'],code:p('"fmt"; "net/http"; "net/http/httptest"','  mux := http.NewServeMux()\n  mux.HandleFunc("GET /health", func(w http.ResponseWriter, r *http.Request) {\n    w.Header().Set("Content-Type", "text/plain; charset=utf-8")\n    fmt.Fprintln(w, "healthy")\n  })\n  response := httptest.NewRecorder()\n  mux.ServeHTTP(response, httptest.NewRequest("GET", "/health", nil))\n  fmt.Println(response.Code)\n  fmt.Print(response.Body.String())'),output:'200\nhealthy\n',watch:'After http.Error, return if the handler should stop. Writing more data can append to the error response.',task:'Add GET /ready that returns status 503 and the text warming up.',hint:'Use http.Error(w, "warming up", http.StatusServiceUnavailable).',solution:'Register mux.HandleFunc("GET /ready", func(w http.ResponseWriter, r *http.Request) { http.Error(w, "warming up", http.StatusServiceUnavailable) }). Test it with a recorder and expect code 503.',quiz:q('When should Content-Type be set?',['After writing the body','Before writing the status or body','Only after the handler returns'],1,'Headers are committed when the response status or first body bytes are sent.')},
{id:'http-middleware',title:'Middleware is handler composition',summary:'Add shared behavior without tangling every endpoint.',explain:['Middleware accepts a handler and returns another handler. It can run logic before and after next.ServeHTTP. Order matters: the outermost wrapper sees the request first and the response last.','Use middleware for consistent request IDs, access logs, recovery boundaries, and authentication checks. Context carries request-scoped information to downstream code. For metrics, a response wrapper must preserve the optional interfaces your handlers depend on.'],code:p('"fmt"; "net/http"; "net/http/httptest"','  handler := withHeader(http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n    fmt.Fprint(w, "ok")\n  }))\n  recorder := httptest.NewRecorder()\n  handler.ServeHTTP(recorder, httptest.NewRequest("GET", "/", nil))\n  fmt.Println(recorder.Header().Get("X-Course"))\n  fmt.Println(recorder.Body.String())','func withHeader(next http.Handler) http.Handler {\n  return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {\n    w.Header().Set("X-Course", "Go by Doing")\n    next.ServeHTTP(w, r)\n  })\n}'),output:'Go by Doing\nok\n',watch:'Call next exactly when the request should proceed. An authentication failure should write its response and return.',task:'Add middleware that rejects a request without an X-Request-ID header.',hint:'Check r.Header.Get before calling next.',solution:'If r.Header.Get("X-Request-ID") == "", call http.Error(w, "missing request id", 400) and return. Otherwise call next.ServeHTTP(w, r). This is an exercise in control flow, not an authentication scheme.',quiz:q('What is the common middleware signature?',['func(http.Handler) http.Handler','func() string','func(*http.Request) error only'],0,'Wrapping handlers makes middleware composable through the standard interface.')},
{id:'http-clients',title:'Clients, deadlines, and response bodies',summary:'Make outbound requests without waiting forever.',explain:['Reuse http.Client and its transport so connections can be pooled. Set an appropriate timeout or use a per-request context deadline. A received HTTP 404 is a response, not a transport error; inspect StatusCode explicitly.','Close response bodies after successful requests. Reading to EOF can help connection reuse, but never read unbounded untrusted bodies just for reuse. The example injects a transport, keeping the request deterministic and independent of an external server.'],code:p('"fmt"; "io"; "net/http"; "strings"; "time"','  client := &http.Client{Timeout: 2 * time.Second, Transport: fakeTransport{}}\n  response, err := client.Get("https://example.com/health")\n  if err != nil { panic(err) }\n  defer response.Body.Close()\n  data, err := io.ReadAll(io.LimitReader(response.Body, 1024))\n  if err != nil { panic(err) }\n  fmt.Println(response.StatusCode, string(data))','type fakeTransport struct{}\nfunc (fakeTransport) RoundTrip(r *http.Request) (*http.Response, error) {\n  return &http.Response{StatusCode: 200, Header: make(http.Header), Body: io.NopCloser(strings.NewReader("ready")), Request: r}, nil\n}'),output:'200 ready\n',watch:'http.DefaultClient has no overall timeout. Pick deadlines based on the operation; retry only when the operation and failure make it safe.',task:'Make the fake transport return status 503 and handle it as a service failure.',hint:'Check StatusCode after checking err.',solution:'Return StatusCode: 503 in RoundTrip. At the caller, if response.StatusCode >= 500 { fmt.Println("upstream unavailable"); return }. Still close response.Body with a defer registered before the check.',quiz:q('Does client.Get return a transport error for HTTP 404?',['Yes, always','No; inspect the response status','Only if the body is empty'],1,'A valid HTTP error response is separate from failure to perform the request.')}
]},
{id:'data-storage',title:'Data & persistence',description:'Learn SQL boundaries, transaction semantics, and cache tradeoffs.',level:'Intermediate',icon:'database',topics:['database/sql','Pooling','Transactions','Caching','Serialization','Migrations'],reference:'https://go.dev/doc/database/',lessons:[
{id:'sql-boundaries',title:'SQL parameters and connection pools',summary:'Keep user input in values, not in query syntax.',explain:['database/sql provides a driver-independent connection pool through *sql.DB. Open one long-lived pool, configure its limits, and pass contexts to queries. A database driver is separate; choose one compatible with your database and runtime.','Pass values as query arguments instead of interpolating them into SQL. Placeholder syntax depends on the database and driver. Identifiers such as column names cannot usually be parameterized: select them from a fixed allowlist. The example shows the query boundary without pretending to contact a database.'],code:p('"fmt"','  name := "Ada\u0027 OR 1=1 --"\n  query := "SELECT id FROM users WHERE name = ?"\n  args := []any{name}\n  fmt.Println(query)\n  fmt.Printf("arguments: %d\\n", len(args))'),output:'SELECT id FROM users WHERE name = ?\narguments: 1\n',watch:'The ? placeholder here illustrates one driver convention. PostgreSQL commonly uses $1. A parameterized query still needs authorization and input validation.',task:'Write the boundary for looking up a user by ID with a context.',hint:'Use db.QueryRowContext(ctx, query, id).Scan(&user.ID, &user.Name), with placeholders matching the chosen driver.',solution:'For a driver using ?: err := db.QueryRowContext(ctx, "SELECT id, name FROM users WHERE id = ?", id).Scan(&user.ID, &user.Name). Handle sql.ErrNoRows separately, and enforce the caller’s access to this user. Integration-test with a real test database.',quiz:q('What does *sql.DB normally represent?',['One permanently reserved connection','A concurrency-safe connection pool','An in-memory table'],1,'sql.DB manages a pool and can be reused across requests.')},
{id:'transactions',title:'Transactions protect invariants',summary:'Make related database changes succeed or fail together.',explain:['Begin a transaction with BeginTx, defer Rollback for unsuccessful exits, execute related statements through the *sql.Tx, then Commit. Do not mix db calls into a transaction accidentally: they may run on unrelated connections.','Atomicity does not by itself prevent every concurrent anomaly. Choose isolation, locking, constraints, or conditional updates based on the invariant. For a transfer, reject an overdraft in the database and ensure the debit and credit belong to one transaction. The example models the invariant in memory; it is not a database transaction.'],code:p('"fmt"','  from, to := 100, 20\n  amount := 30\n  if amount <= 0 || from < amount { panic("invalid transfer") }\n  from, to = from-amount, to+amount\n  fmt.Println(from, to)\n  fmt.Println("total:", from+to)'),output:'70 50\ntotal: 120\n',watch:'A check-then-update sequence can race. Use database constraints and an atomic condition, and inspect affected rows. Commit itself can fail.',task:'Design a SQL transfer that cannot make the source balance negative.',hint:'Use UPDATE ... SET balance = balance - ? WHERE id = ? AND balance >= ? within a transaction.',solution:'Begin a transaction; conditionally debit the source, require exactly one affected row, credit the destination and require one affected row, then commit. Roll back on any failure. Test simultaneous transfers and define retry handling for serialization conflicts.',quiz:q('Which handle should execute transaction statements?',['The original db handle','The *sql.Tx handle','A newly opened database pool'],1,'Statements executed through the transaction handle belong to that transaction.')},
{id:'cache-invalidation',title:'Caches, TTLs, and stale data',summary:'Treat a cache as a policy, not a second source of truth.',explain:['A cache trades freshness and memory for lower latency or less backend work. Decide what a miss means, how long data can be stale, and what happens during a backend failure. Cache-aside loads the source on a miss and stores the result.','TTL is one invalidation tool, not a correctness guarantee. Concurrent misses can stampede the backend; coalescing duplicate work or limiting refresh concurrency can help. Shared caches need synchronization, bounded size, and careful key design. This example makes the clock explicit for deterministic expiration.'],code:p('"fmt"; "time"','  now := time.Unix(0, 0)\n  entry := Entry{Value: "cached profile", Expires: now.Add(time.Minute)}\n  fmt.Println(entry.Valid(now.Add(30 * time.Second)))\n  fmt.Println(entry.Valid(now.Add(2 * time.Minute)))','type Entry struct { Value string; Expires time.Time }\nfunc (e Entry) Valid(now time.Time) bool { return now.Before(e.Expires) }'),output:'true\nfalse\n',watch:'Do not cache authorization decisions or user-specific responses under keys that omit security context. Expired entries also need eviction.',task:'Define the cache policy for a public product price versus an account balance.',hint:'Describe freshness requirements and failure behavior for each.',solution:'A product display may permit a short documented TTL, while checkout must validate the authoritative price. An account balance generally needs authoritative reads or explicit consistency guarantees. Never assume the same TTL fits both.',quiz:q('Does a TTL guarantee immediate consistency after a write?',['Yes','No','Only for string keys'],1,'A cached value can remain stale until expiration unless another invalidation mechanism updates it.')}
]},
{id:'application-design',title:'Structure real applications',description:'Build CLIs, inject dependencies, and organize code around behavior.',level:'Intermediate',icon:'puzzle',topics:['CLI','Flags','Configuration','Dependency injection','Package design','API contracts'],reference:'https://go.dev/doc/modules/layout',lessons:[
{id:'cli-config',title:'Command-line tools and configuration',summary:'Make behavior discoverable and configuration explicit.',explain:['The flag package handles simple command-line options. Keep argument parsing at the boundary, validate configuration once, and pass typed settings to application code. Use stderr for diagnostics and stdout for machine-consumable results.','Choose and document precedence, for example flags over environment variables over defaults. Environment variables are strings and may be absent or malformed. Avoid package init functions that quietly read environment state; explicit construction is easier to test.'],code:p('"flag"; "fmt"; "io"','  flags := flag.NewFlagSet("greet", flag.ContinueOnError)\n  flags.SetOutput(io.Discard)\n  name := flags.String("name", "developer", "who to greet")\n  if err := flags.Parse([]string{"-name", "Ada"}); err != nil { panic(err) }\n  fmt.Println("Hello,", *name)'),output:'Hello, Ada\n',watch:'Do not print secrets when logging configuration. Distinguish unset environment variables from intentionally empty values when that matters.',task:'Add a -count flag and reject values outside 1 through 5.',hint:'Use flags.Int, then validate the dereferenced result after parsing.',solution:'Declare count := flags.Int("count", 1, "number of greetings"). After Parse, return a clear usage error when *count < 1 || *count > 5. Keep exit-code decisions in main so the underlying logic stays testable.',quiz:q('Where should configuration normally be validated?',['Repeatedly in every helper','At a clear application boundary','Only after the first failure'],1,'Early validation makes errors understandable and keeps core logic focused.')},
{id:'dependency-injection',title:'Dependency injection without a framework',summary:'Pass what a function needs and testing becomes easier.',explain:['Dependency injection means providing collaborators rather than constructing hidden ones inside business logic. In Go, constructors, function parameters, and small interfaces usually suffice. Use concrete types until an abstraction buys a useful boundary.','Keep interfaces near the consuming package. A test can supply a deterministic fake, while production supplies a database, clock, or remote client. Do not create an interface for every struct automatically; extra abstractions also carry maintenance cost.'],code:p('"fmt"','  service := Service{Lookup: func(id int) string { return "Ada" }}\n  fmt.Println(service.Greet(42))','type Service struct { Lookup func(int) string }\nfunc (s Service) Greet(id int) string { return "Hello, " + s.Lookup(id) }'),output:'Hello, Ada\n',watch:'A fake that ignores essential behavior can hide defects. Use integration tests to verify real database and protocol boundaries.',task:'Inject a clock into an expiry checker.',hint:'Accept now func() time.Time instead of calling time.Now deep inside the logic.',solution:'Create a struct with Now func() time.Time and compare expiry with s.Now(). Production passes time.Now; a test passes a function returning a fixed time. Check before, at, and after the expiration boundary.',quiz:q('What is dependency injection in this context?',['A required external framework','Passing collaborators explicitly','Using global variables for all services'],1,'Explicit dependencies reveal requirements and let tests control external effects.')},
{id:'package-design',title:'Package boundaries and maintainable APIs',summary:'Organize around capabilities and keep contracts small.',explain:['A good package has a clear purpose and a small public surface. Group code around concepts such as payments or catalog, rather than forcing every project into controllers/services/repositories. internal directories restrict imports to permitted parent trees.','Avoid import cycles: move ownership to the right layer or introduce a focused boundary at the consumer. Document concurrency safety and error behavior as part of an API. A constructor can validate invariants so later methods operate on a usable value.'],code:p('"fmt"','  queue, err := NewQueue(8)\n  if err != nil { panic(err) }\n  fmt.Println("capacity:", queue.Capacity())','type Queue struct { capacity int }\nfunc NewQueue(capacity int) (*Queue, error) {\n  if capacity <= 0 { return nil, fmt.Errorf("capacity must be positive") }\n  return &Queue{capacity: capacity}, nil\n}\nfunc (q *Queue) Capacity() int { return q.capacity }'),output:'capacity: 8\n',watch:'A folder hierarchy is not architecture by itself. Check whether dependencies and invariants remain understandable as features change.',task:'Split a command into a small main package and a reusable internal application package.',hint:'Keep process concerns such as flags and exit codes in main.',solution:'Have main load configuration and construct dependencies, then call an internal package’s Run(ctx, config, dependencies). Return errors to main for reporting. Do not move every two-line function into a separate package.',quiz:q('What does an internal directory enforce?',['Faster compilation','An import visibility boundary','Automatic dependency injection'],1,'Go restricts which packages may import code beneath an internal directory.')}
]},
{id:'security',title:'Security by construction',description:'Validate inputs, understand identity boundaries, and protect secrets.',level:'Advanced',icon:'lock',topics:['Validation','Authentication','Authorization','crypto/rand','HMAC','TLS','Vulnerabilities'],reference:'https://go.dev/doc/security/',lessons:[
{id:'input-boundaries',title:'Validate at trust boundaries',summary:'Limit size, shape, and meaning before accepting data.',explain:['External input needs explicit limits and validation. For an HTTP body, use http.MaxBytesReader to enforce a size limit, decode into a typed structure, and validate allowed values. Avoid exposing raw internal errors to clients.','Input validation is not authorization. Even a valid resource ID must be checked against the caller’s permissions. When fetching user-supplied URLs, consider SSRF and redirect behavior; when handling filenames, define where access is permitted instead of merely removing suspicious characters.'],code:p('"fmt"; "strings"','  for _, name := range []string{"Ada", "   ", strings.Repeat("x", 81)} {\n    fmt.Println(validName(name))\n  }','func validName(name string) bool {\n  name = strings.TrimSpace(name)\n  return len(name) > 0 && len(name) <= 80\n}'),output:'true\nfalse\nfalse\n',watch:'This example uses a byte-length policy, not a character count. Document your policy. Validation cannot replace output encoding or parameterized SQL.',task:'Specify validation rules for a create-user request.',hint:'Separate syntactic checks from domain and permission checks.',solution:'Define maximum body size, reject unknown fields if appropriate, require one JSON document, trim and validate the name, validate email with a deliberate policy, and authorize user creation. Return field-level client errors without revealing secrets.',quiz:q('Does a well-formed object ID prove the caller can access it?',['Yes','No; authorization is a separate check','Only if it is numeric'],1,'Validation checks whether input is acceptable; authorization checks whether this actor may perform this action.')},
{id:'crypto-auth',title:'Randomness, signatures, and identity',summary:'Use the right primitives and keep authentication distinct from access.',explain:['Use crypto/rand for security-sensitive randomness, not math/rand. Store and transmit secrets through deliberate mechanisms, avoid logging them, and use established password-hashing and authentication libraries rather than inventing a password scheme.','HMAC authenticates a message using a shared secret; compare with hmac.Equal. It does not encrypt the message. Authentication establishes identity, while authorization checks allowed actions. HTTPS protects transport but does not automatically enforce either.'],code:p('"crypto/hmac"; "crypto/sha256"; "fmt"','  key := []byte("teaching-key-only")\n  message := []byte("job:42")\n  signature := sign(key, message)\n  fmt.Println(hmac.Equal(signature, sign(key, message)))\n  fmt.Println(hmac.Equal(signature, sign(key, []byte("job:43"))))','func sign(key, message []byte) []byte {\n  mac := hmac.New(sha256.New, key)\n  mac.Write(message)\n  return mac.Sum(nil)\n}'),output:'true\nfalse\n',watch:'The hardcoded key is for this deterministic lesson only. Real secrets need secure generation, storage, rotation, and a protocol that addresses replay.',task:'Generate a 32-byte token with crypto/rand and encode it for a URL.',hint:'Use rand.Read and base64.RawURLEncoding.EncodeToString.',solution:'Create token := make([]byte, 32); call crypto/rand.Read(token) and handle the error; encode with base64.RawURLEncoding.EncodeToString(token). Store only the representation your protocol needs, define expiration, and never log the token.',quiz:q('What does HMAC provide?',['Encryption','Message authentication using a shared key','Automatic user authorization'],1,'HMAC helps verify integrity and possession of the shared secret; it does not hide message content.')},
{id:'supply-chain',title:'Dependencies and vulnerability review',summary:'Treat upgrades as a tested engineering change.',explain:['A dependency adds code and maintenance obligations. Review its purpose, license, maintenance state, and transitive dependencies. Use go list -m all to inspect the module graph and go mod tidy to remove unnecessary requirements.','govulncheck uses Go vulnerability information with program analysis to help identify relevant known vulnerabilities. Review the findings, update intentionally, run tests, and record the change. A clean scan is useful evidence, not proof that software has no security defects.'],code:p('"fmt"; "runtime/debug"','  _, ok := debug.ReadBuildInfo()\n  fmt.Println("build info:", ok)\n  if ok { fmt.Println("module metadata available") }'),output:'build info: true\nmodule metadata available\n',watch:'Do not solve a vulnerability by blindly upgrading every package. Check compatibility, affected code paths, and the actual fix.',task:'Add a dependency-review step to a project’s CI plan.',hint:'Include tests, a known-vulnerability scan, and review of module-file changes.',solution:'Run go test ./..., go vet ./..., and govulncheck ./... after installing a reviewed scanner version. Review go.mod/go.sum changes and relevant advisories. Pin CI tool versions intentionally and revisit them over time.',quiz:q('Does a clean vulnerability scan prove an application is secure?',['Yes','No; it covers known findings within the tool’s scope','Only if there are no dependencies'],1,'Unknown issues, design flaws, deployment configuration, and unexercised assumptions still require review.')}
]},
{id:'observability',title:'Reliability & observability',description:'Make production behavior understandable and failure recoverable.',level:'Advanced',icon:'activity',topics:['slog','Metrics','Tracing','Retries','Idempotency','Shutdown'],reference:'https://pkg.go.dev/log/slog',lessons:[
{id:'structured-logging',title:'Structured logs, useful signals',summary:'Give each event context that can be searched.',explain:['log/slog records structured attributes alongside a message and severity. Use consistent keys such as request_id, operation, and duration. Add context near the boundary where an error becomes actionable; avoid emitting the same error repeatedly at every layer.','Logs explain individual events, metrics summarize behavior, and traces connect work across boundaries. Avoid high-cardinality metric labels such as raw user IDs. Redact credentials and personal data before recording them.'],code:p('"bytes"; "fmt"; "log/slog"','  var output bytes.Buffer\n  handler := slog.NewJSONHandler(&output, &slog.HandlerOptions{\n    ReplaceAttr: func(groups []string, attr slog.Attr) slog.Attr {\n      if attr.Key == slog.TimeKey { return slog.Attr{} }; return attr\n    },\n  })\n  logger := slog.New(handler)\n  logger.Info("job finished", "job_id", 42, "items", 3)\n  fmt.Print(output.String())'),output:'{"level":"INFO","msg":"job finished","job_id":42,"items":3}\n',watch:'Request bodies and authorization headers can contain secrets. Logging everything is not observability.',task:'Choose three signals for an HTTP service.',hint:'Start with request rate, errors, and latency; describe the decision each supports.',solution:'Measure requests by route template, error rate by bounded status class, and latency distributions by operation. Use logs with request IDs for diagnosis and traces for downstream relationships. Keep labels bounded.',quiz:q('Which is a poor metric label?',['HTTP method','Bounded status class','Every unique request ID'],2,'Unbounded request IDs create very high cardinality and can make metrics storage expensive or unusable.')},
{id:'retry-idempotency',title:'Retries, backoff, and idempotency',summary:'A retry is another attempt to change the world.',explain:['Retry transient failures only when repeating the operation is safe or the protocol can deduplicate it. An ambiguous timeout may mean the server completed the write but the client missed the response. An idempotency key can identify repeated attempts at one logical operation.','Use bounded attempts, a total time budget, exponential backoff, and jitter to avoid synchronized retry storms. Observe cancellation while waiting. The example computes capped delays deterministically; production jitter should vary attempts without weakening a security guarantee.'],code:p('"fmt"; "time"','  for attempt := 0; attempt < 5; attempt++ {\n    delay := 100 * time.Millisecond * time.Duration(1<<attempt)\n    if delay > time.Second { delay = time.Second }\n    fmt.Println(delay)\n  }'),output:'100ms\n200ms\n400ms\n800ms\n1s\n',watch:'Do not retry every error or every HTTP method automatically. A non-idempotent write can be duplicated even after a timeout.',task:'Design retry rules for a payment submission.',hint:'Include a stable idempotency key, stored request identity, and handling of an unknown result.',solution:'Reuse one key for all attempts of the same payment, store and enforce it server-side, reject conflicting payloads for a reused key, and return the prior result when known. Bound retries and reconcile ambiguous outcomes instead of charging again with a new key.',quiz:q('What can a client timeout mean after a write?',['The server definitely did nothing','The server may have completed the write','The request is automatically rolled back'],1,'A lost response can leave the outcome unknown, which makes retry safety essential.')},
{id:'graceful-shutdown',title:'Graceful shutdown and lifecycle ownership',summary:'Stop accepting work, finish bounded work, then exit.',explain:['A process should own the lifecycle of its server and background workers. signal.NotifyContext can convert termination signals into cancellation. http.Server.Shutdown stops new connections and waits for active handlers subject to a context deadline.','Use a fresh bounded shutdown context: the main application context may already be canceled. Stop producers before closing shared job channels. Wait for workers where appropriate, close resources, and define what happens to unfinished durable work.'],code:p('"context"; "fmt"; "time"','  app, stop := context.WithCancel(context.Background())\n  stop()\n  fmt.Println("application:", app.Err())\n  shutdown, cancel := context.WithTimeout(context.Background(), 5*time.Second)\n  defer cancel()\n  fmt.Println("shutdown context active:", shutdown.Err() == nil)'),output:'application: context canceled\nshutdown context active: true\n',watch:'Passing the already-canceled application context into Shutdown can prevent graceful waiting. Shutdown also does not automatically manage every application-owned goroutine.',task:'Write the shutdown order for an API plus background queue worker.',hint:'Consider readiness, new work, in-flight requests, producer ownership, and a final deadline.',solution:'Mark unready, stop accepting requests, stop queue producers, let or ask workers to finish within a fresh deadline, persist/release unfinished jobs according to the queue protocol, then close dependencies. Ensure main waits for the sequence.',quiz:q('Why use a fresh context for bounded shutdown?',['To ignore time limits','The application context may already be canceled','Contexts cannot be reused by handlers'],1,'A fresh deadline allows cleanup time after the cancellation that initiated shutdown.')}
]},
{id:'performance',title:'Performance & the runtime',description:'Understand memory and scheduling, then measure before changing code.',level:'Advanced',icon:'gauge',topics:['Allocations','Escape analysis','GC','pprof','Scheduler','Atomics'],reference:'https://go.dev/doc/diagnostics',lessons:[
{id:'allocations-gc',title:'Allocations, escape analysis, and GC',summary:'Learn where memory costs come from.',explain:['The compiler decides whether values can stay on a goroutine’s stack or need heap allocation. Returning an address is safe in Go: escape analysis arranges a valid lifetime. Source-level use of new or a pointer does not alone tell you the final allocation cost.','The garbage collector reclaims unreachable heap objects. Allocation rate and live heap size influence its work. Inspect compiler decisions with go build -gcflags=-m, measure allocations with benchmarks, and avoid retaining large backing arrays unnecessarily.'],code:p('"fmt"','  pointer := newCount()\n  fmt.Println(*pointer)\n  source := []int{1, 2, 3, 4}\n  kept := append([]int(nil), source[:1]...)\n  fmt.Println(kept)','func newCount() *int {\n  count := 42\n  return &count\n}'),output:'42\n[1]\n',watch:'A tiny subslice can keep a large array reachable. A shallow copy helps detach the outer array but may still retain nested objects.',task:'Compare retaining a one-item view with retaining a one-item copy of a large slice.',hint:'Measure heap retention after dropping other references; do not rely only on len.',solution:'Build a representative benchmark or heap-profile experiment, keep either source[:1] or a copied one-element slice, and discard the other source reference. Inspect retained heap. Explain the extra copy cost alongside the retention reduction.',quiz:q('Is returning a pointer to a local Go variable safe?',['No, always dangling','Yes, the compiler/runtime preserve its lifetime','Only for global variables'],1,'Go’s memory management and escape analysis ensure referenced values outlive their valid uses.')},
{id:'profiling',title:'Read profiles before changing code',summary:'Find where the real workload spends time and memory.',explain:['CPU profiles sample where execution spends time. Heap profiles show allocated or live memory depending on the view. Block and mutex profiles help identify waiting and contention. Use go tool pprof to inspect profiles captured by tests or a carefully exposed diagnostic endpoint.','Compare profiles under representative load, with a stable baseline and correctness checks. The example calculates the same result in a loop and with a formula; the formula reduces work for this domain, but arithmetic range and overflow still matter.'],code:p('"fmt"','  const n = 100\n  total := 0\n  for i := 1; i <= n; i++ { total += i }\n  formula := n * (n + 1) / 2\n  fmt.Println(total, formula)'),output:'5050 5050\n',watch:'Do not expose diagnostic endpoints broadly on a production public interface. Profiles can reveal implementation and workload information.',task:'Capture a CPU profile for a benchmark in a local project.',hint:'Use go test -bench=. -cpuprofile=cpu.out and inspect with go tool pprof.',solution:'Run the benchmark with -cpuprofile=cpu.out, open go tool pprof cpu.out, and inspect top and list output. Check whether time is in the expected code or in allocation, locking, or external waits. Re-measure after a change.',quiz:q('Which profile is most directly useful for retained objects?',['Heap profile','Git history','A source-code line count'],0,'A heap profile can reveal which allocation paths keep memory live.')},
{id:'scheduler-atomics',title:'Scheduling, parallelism, and atomics',summary:'Concurrency describes structure; parallelism describes execution.',explain:['Goroutines are scheduled onto operating-system threads. GOMAXPROCS controls how many OS threads can execute user Go code simultaneously; it is not a goroutine count. More workers can increase contention or memory use instead of improving throughput.','sync/atomic supports specific atomic operations and memory ordering. Typed atomics can suit independent counters or carefully designed state machines. A mutex is often clearer when several values must change under one invariant. Never casually mix atomic and non-atomic access to the same shared state.'],code:p('"fmt"; "sync"; "sync/atomic"','  var count atomic.Int64\n  var wg sync.WaitGroup\n  for i := 0; i < 4; i++ {\n    wg.Add(1)\n    go func() { defer wg.Done(); count.Add(1) }()\n  }\n  wg.Wait()\n  fmt.Println(count.Load())'),output:'4\n',watch:'An atomic counter does not protect other related fields. Do not copy atomic values after use.',task:'Explain when a mutex is preferable to two atomic counters.',hint:'Think about an invariant involving both values.',solution:'If balance and reserved funds must satisfy a relationship, changing each atomically can still expose inconsistent combinations. Use one mutex around the combined state transition, or a carefully proven alternative.',quiz:q('Does launching more goroutines guarantee more throughput?',['Yes','No; workload and resource contention matter','Only with buffered channels'],1,'Concurrency must be bounded and measured against CPU, I/O, memory, and downstream capacity.')}
]},
{id:'advanced-go',title:'Beyond everyday Go',description:'Explore networking, reflection, code generation, and interoperability.',level:'Advanced',icon:'sparkles',topics:['TCP','UDP','Reflection','Code generation','cgo','unsafe','Build constraints'],reference:'https://pkg.go.dev/reflect',lessons:[
{id:'network-protocols',title:'TCP streams, framing, and deadlines',summary:'A network read is not necessarily one whole message.',explain:['TCP provides an ordered byte stream, not message boundaries. Define framing with a delimiter, length prefix, or existing protocol. Handle partial reads and writes; io.ReadFull is useful when the protocol requires a fixed number of bytes. UDP uses datagrams with different delivery and ordering guarantees.','Set deadlines on network operations and bound frame sizes before allocating. A parser should reject truncated and oversized messages. The example uses an in-memory stream so it tests framing without network access.'],code:p('"bytes"; "encoding/binary"; "fmt"; "io"','  wire := []byte{0, 3, 71, 111, 33}\n  reader := bytes.NewReader(wire)\n  var size uint16\n  if err := binary.Read(reader, binary.BigEndian, &size); err != nil { panic(err) }\n  if size > 1024 { panic("frame too large") }\n  payload := make([]byte, size)\n  if _, err := io.ReadFull(reader, payload); err != nil { panic(err) }\n  fmt.Println(string(payload))'),output:'Go!\n',watch:'A single Read may return fewer bytes than requested. Validate the announced length before allocating memory.',task:'Change the declared size from 3 to 4 and identify the parser error.',hint:'Only three payload bytes remain after the length prefix.',solution:'io.ReadFull returns io.ErrUnexpectedEOF because it reads some payload but cannot fill the four-byte buffer. In application code, return a protocol error rather than panic.',quiz:q('What does TCP preserve?',['One application message per Read','An ordered byte stream','A guarantee that every write arrives in one packet'],1,'Application protocols must define their own framing over TCP’s byte stream.')},
{id:'reflection-generation',title:'Reflection and code generation',summary:'Reach for dynamic inspection only when the boundary needs it.',explain:['reflect inspects types and values at runtime. It powers tools such as serialization and generic validation, but reflection can introduce runtime errors and obscure ordinary control flow. Prefer direct code, interfaces, or type parameters when they express the problem clearly.','go generate runs explicitly declared generator commands; it is not executed automatically by go build. Generated source should be reproducible, reviewed, and marked with the standard generated-code comment. Generation can move repeated work from runtime into build-time tooling.'],code:p('"fmt"; "reflect"','  t := reflect.TypeOf(Profile{})\n  for i := 0; i < t.NumField(); i++ {\n    field := t.Field(i)\n    fmt.Println(field.Name, field.Tag.Get("json"))\n  }','type Profile struct {\n  Name string `json:"name"`\n  Age int `json:"age"`\n}'),output:'Name name\nAge age\n',watch:'Reflective mutation requires a settable value, often reached through a pointer. Invalid assumptions can panic at runtime.',task:'Choose between reflection and generation for a serializer with a fixed schema.',hint:'Consider runtime flexibility, performance, reviewability, and maintenance.',solution:'A fixed schema can suit generated or hand-written typed code with compile-time checks. Reflection is useful when types are discovered dynamically. Benchmark only if serialization is a measured bottleneck, and keep generated outputs reproducible.',quiz:q('Does go build automatically execute go generate?',['Yes','No','Only for main packages'],1,'go generate is a separate, explicit developer workflow.')},
{id:'interop-builds',title:'cgo, unsafe, and platform boundaries',summary:'Know the cost before crossing a language or memory boundary.',explain:['cgo allows Go code to call C, but introduces a C toolchain, pointer-passing rules, and deployment complexity. unsafe bypasses parts of Go’s type safety and should be isolated behind carefully reviewed boundaries. Neither belongs in ordinary application code without a concrete need.','Use build constraints and GOOS/GOARCH to select platform-specific implementations. Pure Go cross-compilation is often straightforward; cgo adds target toolchain requirements. Test each supported target instead of assuming a successful cross-build proves runtime behavior.'],code:p('"fmt"; "unsafe"','  var small uint8\n  var large uint64\n  fmt.Println(unsafe.Sizeof(small), unsafe.Sizeof(large))'),output:'1 8\n',watch:'unsafe.Sizeof reports the immediate value’s size, not all referenced data. A slice header’s size does not include its backing array.',task:'Explain why unsafe.Sizeof(slice) is not a measure of the slice’s total memory usage.',hint:'Separate the descriptor, backing array, and any objects referenced by elements.',solution:'A slice value is a descriptor. Its backing array is separate, and pointer-containing elements may refer to further allocations. Capacity, element size, sharing, and retained objects all affect memory use. Use profiles for real retention analysis.',quiz:q('What extra concern does cgo introduce?',['No additional tooling','A C toolchain and interoperability constraints','Automatic memory safety for arbitrary C code'],1,'cgo crosses a language/runtime boundary and requires careful build, ownership, and pointer-rule handling.')}
]},
{id:'shipping',title:'Ship & maintain Go software',description:'Build repeatable releases, evolve modules, and operate what you ship.',level:'Advanced',icon:'rocket',topics:['Builds','Containers','CI','Semantic versions','Migrations','Review'],reference:'https://go.dev/doc/modules/release-workflow',lessons:[
{id:'build-release',title:'Repeatable builds and container delivery',summary:'Ship the program and its actual runtime requirements.',explain:['go build creates an executable for a command package. Record the source revision and toolchain used for a release. Pure Go programs can often target another OS and architecture with GOOS and GOARCH; cgo and runtime dependencies need additional consideration.','A small container image is useful only if the program still has the certificates, timezone data, permissions, and files it needs. Run as an appropriate non-root user and set resource limits. Build once, verify the artifact, then promote that artifact through environments.'],code:p('"fmt"','  fmt.Println("version:", version)\n  fmt.Println("revision:", revision)','var version = "dev"\nvar revision = "unknown"'),output:'version: dev\nrevision: unknown\n',watch:'A Go binary is not universally static. Verify cgo linkage and OS/runtime dependencies before choosing a minimal base image.',task:'Build the example with a release version injected through linker flags.',hint:'Use -ldflags with -X main.version and -X main.revision.',solution:'Run go build -ldflags="-X main.version=1.0.0 -X main.revision=abc123" -o app . and execute the resulting artifact on its intended platform. In a real pipeline, use the verified source revision rather than a hand-written placeholder.',quiz:q('What should be promoted between environments?',['An independently rebuilt artifact each time','The same verified release artifact','Only source comments'],1,'Promoting the same artifact reduces differences between what was tested and what is deployed.')},
{id:'ci-maintenance',title:'CI checks that catch meaningful failures',summary:'Automate confidence without pretending checks are proof.',explain:['A useful CI pipeline checks formatting, compilation, tests, static analysis, and dependency security. Add race detection where the supported environment and workload justify it. Keep deterministic unit tests fast; use integration tests for real external boundaries.','Choose toolchain and tool versions intentionally, cache dependencies safely, and retain useful failure diagnostics. Test schema migrations against realistic starting states and validate compatibility during rolling deployments. A pipeline should expose the failure, not hide it behind endless retries.'],code:p('"fmt"','  checks := []string{"format", "vet", "test", "build", "security"}\n  for index, check := range checks { fmt.Printf("%d. %s\\n", index+1, check) }'),output:'1. format\n2. vet\n3. test\n4. build\n5. security\n',watch:'This program lists a pipeline; it does not run those checks. Configure the actual CI provider to execute and enforce them.',task:'Write CI acceptance criteria for a small API.',hint:'Include behavior, security, race-sensitive code, and a real deployment artifact.',solution:'Require clean formatting, go vet ./..., go test ./..., a build, and reviewed vulnerability results. Add database integration tests and go test -race for relevant paths. Verify the produced artifact and preserve logs for failed checks.',quiz:q('What should CI do with a consistently failing test?',['Retry forever','Report a failure that must be investigated','Silently skip it'],1,'Retries can hide defects. A failing check needs diagnosis and a deliberate resolution.')},
{id:'module-evolution',title:'Versioning and evolving public APIs',summary:'Make changes users can adopt safely.',explain:['Semantic versioning communicates compatibility intent. In Go modules, v2 and later generally use a major-version suffix in the module path. Public APIs include exported types and behavior, error contracts, concurrency guarantees, and data formats—not only function signatures.','Before releasing, document changes, run compatibility and behavior tests, and tag the intended source revision. Prefer an additive migration path where practical. Remove dead dependencies and revisit examples when the supported language or ecosystem changes.'],code:p('"fmt"','  fmt.Println("v1:", "example.com/team/client")\n  fmt.Println("v2:", "example.com/team/client/v2")'),output:'v1: example.com/team/client\nv2: example.com/team/client/v2\n',watch:'A change can break callers even if it still compiles—for example, changing error behavior or whether a method is safe for concurrent use.',task:'Plan a migration from a string ID parameter to a structured ID type in a public library.',hint:'Consider a parallel API, deprecation period, adapters, and a major release if compatibility cannot be preserved.',solution:'Introduce the structured type and an additive method if practical, document conversion and validation, keep the old method working during a transition, and test behavior. If an incompatible signature change is required, release under the appropriate new major module path.',quiz:q('Which change can break API compatibility?',['Changing documented error behavior','Adding an internal comment','Running gofmt'],0,'Callers depend on behavioral contracts as well as compile-time signatures.')}
]},
];

export const allLessons = modules.flatMap((module, moduleIndex) => module.lessons.map((lesson, lessonIndex) => ({...lesson, moduleId: module.id, moduleTitle: module.title, level: module.level, reference: module.reference, moduleIndex, lessonIndex, minutes: 6 + (module.level === 'Advanced' ? 4 : module.level === 'Intermediate' ? 2 : 0)})));
export type EnrichedLesson = typeof allLessons[number];
